WITH account_stats AS (SELECT account_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, ROUND(STDDEV(amount), 2) AS stddev_amount FROM transactions WHERE is_flagged GROUP BY account_id) SELECT accounts.opened_date, accounts.account_type, account_stats.merchant_values, account_stats.stddev_amount FROM accounts JOIN account_stats ON accounts.id = account_stats.account_id WHERE account_stats.stddev_amount >= 20 ORDER BY stddev_amount DESC;
